import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("upload vendor documents", () => {
  test("rejects an empty file with empty_file", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Empty"), category: "software", contact_email: "ops@vendor-intake.com" },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "empty.txt", mimeType: "text/plain", buffer: Buffer.alloc(0) },
      },
    });

    expect(res.status(), await res.text()).toBe(422);
    expect((await res.json()).error.code, await res.text()).toBe("empty_file");
  });

  test("rejects a file of 10 MiB + 1 byte with file_too_large", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Big"), category: "software", contact_email: "ops@vendor-intake.com" },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "big.txt", mimeType: "text/plain", buffer: Buffer.alloc(TEN_MIB + 1, "x") },
      },
    });

    expect(res.status(), await res.text()).toBe(413);
    expect((await res.json()).error.code, await res.text()).toBe("file_too_large");
  });

  test("rejects a .exe file with unsupported_type", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Exe"), category: "software", contact_email: "ops@vendor-intake.com" },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "tool.exe", mimeType: "application/octet-stream", buffer: Buffer.from("MZ") },
      },
    });

    expect(res.status(), await res.text()).toBe(415);
    expect((await res.json()).error.code, await res.text()).toBe("unsupported_type");
  });

  test("rejects an unknown document kind with validation_error", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Kind"), category: "software", contact_email: "ops@vendor-intake.com" },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "passport",
        file: { name: "w9.txt", mimeType: "text/plain", buffer: Buffer.from("valid text") },
      },
    });

    expect(res.status(), await res.text()).toBe(422);
    expect((await res.json()).error.code, await res.text()).toBe("validation_error");
  });
});
